     ssize_t ret;

     ret = read_sync(ioc, buf, sizeof(buf));
    if (ret < 0) {
         return ret;
     }
    if (ret != sizeof(buf)) {
        LOG("read failed");
        return -EINVAL;
    }

    /* Reply
