 		mutex_lock(&kvm->lock);
 		list_del(&dev->vm_node);
 		mutex_unlock(&kvm->lock);
 		ops->destroy(dev);
 		return ret;
 	}

	kvm_get_kvm(kvm);
 	cd->fd = ret;
 	return 0;
 }

